sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    if (current.task_status.toString() == 'Completed' &&
        current.completion_date.nil()) {

        gs.addErrorMessage(
            'A Completed Clinical Task must have a Completion Date.'
        );

        current.setAbortAction(true);
    }

})(current, previous);
